class Codec {
public:
    // Encodes a tree to a single string.
    string serialize(TreeNode* root) {
        string s;
        serializeHelper(root, s);
        if (!s.empty() && s.back() == ',') s.pop_back(); // remove trailing comma
        return s;
    }

    // Decodes your encoded data to tree.
    TreeNode* deserialize(string data) {
        if (data.empty()) return nullptr;
        vector<string> tokens;
        string cur;
        for (char c : data) {
            if (c == ',') {
                tokens.push_back(cur);
                cur.clear();
            } else {
                cur.push_back(c);
            }
        }
        tokens.push_back(cur); // last token
        int idx = 0;
        return deserializeHelper(tokens, idx);
    }

private:
    void serializeHelper(TreeNode* node, string& out) {
        if (!node) {
            out += "#,";
            return;
        }
        out += to_string(node->val) + ',';
        serializeHelper(node->left, out);
        serializeHelper(node->right, out);
    }

    TreeNode* deserializeHelper(const vector<string>& tokens, int& idx) {
        if (idx >= (int)tokens.size()) return nullptr;
        const string& val = tokens[idx++];
        if (val == "#") return nullptr;
        TreeNode* node = new TreeNode(stoi(val));
        node->left  = deserializeHelper(tokens, idx);
        node->right = deserializeHelper(tokens, idx);
        return node;
    }
};
